__device__ inline float decode_2mad_f(uint64_t x)
{
    x = x * 264435761u + 1013904223u;
    x = ((x * 1664525u) >> 32) + x;
    int32_t c = (int32_t) __dp4a((uint32_t) x, 0x01010101u, 0xFFFFFE02u);
    float y = __int2float_rn(c) * 0.008415f;
